-- ============================================================
-- TrafficWatch AI — Database Functions & Stored Procedures
-- ============================================================
-- Run after: 00001_init.sql
-- ============================================================

-- INCIDENT STATISTICS
CREATE OR REPLACE FUNCTION public.get_incident_counts() RETURNS TABLE(status TEXT, count BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT i.status::TEXT, COUNT(*)::BIGINT FROM public.incidents i GROUP BY i.status ORDER BY i.status; END; $$;
CREATE OR REPLACE FUNCTION public.get_daily_trends(p_since TIMESTAMPTZ DEFAULT (now()-interval '30 days')) RETURNS TABLE(date TEXT, count BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT to_char(i.created_at,'YYYY-MM-DD') AS date, COUNT(*)::BIGINT FROM public.incidents i WHERE i.created_at>=p_since GROUP BY to_char(i.created_at,'YYYY-MM-DD') ORDER BY date; END; $$;
CREATE OR REPLACE FUNCTION public.get_weekly_trends(p_since TIMESTAMPTZ DEFAULT (now()-interval '90 days')) RETURNS TABLE(date TEXT, count BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT to_char(date_trunc('week',i.created_at),'YYYY-MM-DD') AS date, COUNT(*)::BIGINT FROM public.incidents i WHERE i.created_at>=p_since GROUP BY date_trunc('week',i.created_at) ORDER BY date; END; $$;

-- COUNTY & GEOGRAPHY STATISTICS
CREATE OR REPLACE FUNCTION public.get_county_stats() RETURNS TABLE(county_code TEXT, county_name TEXT, incident_count BIGINT, resolved_count BIGINT, most_common_violation TEXT) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT COALESCE(i.county_code,'UNKNOWN'), COALESCE(c.name,'Unknown'), COUNT(*)::BIGINT, COUNT(*) FILTER(WHERE i.status IN ('resolved','closed'))::BIGINT, (SELECT vt.name FROM public.incident_violations iv JOIN public.violation_types vt ON vt.id=iv.violation_type_id JOIN public.incidents i2 ON i2.id=iv.incident_id WHERE COALESCE(i2.county_code,'UNKNOWN')=COALESCE(i.county_code,'UNKNOWN') GROUP BY vt.name ORDER BY COUNT(*) DESC LIMIT 1) FROM public.incidents i LEFT JOIN public.counties c ON c.code=i.county_code GROUP BY i.county_code, c.name ORDER BY incident_count DESC; END; $$;
CREATE OR REPLACE FUNCTION public.get_incident_geo_distribution() RETURNS TABLE(county_code TEXT, county_name TEXT, count BIGINT, lat DECIMAL, lng DECIMAL) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT COALESCE(i.county_code,'UNKNOWN'), COALESCE(c.name,'Unknown'), COUNT(*)::BIGINT, COALESCE(c.center_lat,0::DECIMAL), COALESCE(c.center_lng,0::DECIMAL) FROM public.incidents i LEFT JOIN public.counties c ON c.code=i.county_code GROUP BY i.county_code, c.name, c.center_lat, c.center_lng ORDER BY count DESC; END; $$;
CREATE OR REPLACE FUNCTION public.get_county_incident_counts() RETURNS TABLE(county_code TEXT, county_name TEXT, incident_count BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT COALESCE(i.county_code,'UNKNOWN'), COALESCE(c.name,'Unknown'), COUNT(*)::BIGINT FROM public.incidents i LEFT JOIN public.counties c ON c.code=i.county_code GROUP BY i.county_code, c.name ORDER BY incident_count DESC; END; $$;

-- OFFICER ACTIVITY
CREATE OR REPLACE FUNCTION public.get_officer_activity(p_since TIMESTAMPTZ DEFAULT (now()-interval '30 days')) RETURNS TABLE(officer_id UUID, officer_name TEXT, incidents_created BIGINT, incidents_resolved BIGINT, evidence_uploaded BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT p.id, p.full_name, COALESCE(ic.incident_count,0)::BIGINT, COALESCE(ir.resolved_count,0)::BIGINT, COALESCE(ev.evidence_count,0)::BIGINT FROM public.profiles p LEFT JOIN (SELECT officer_id, COUNT(*) AS incident_count FROM public.incidents WHERE created_at>=p_since GROUP BY officer_id) ic ON ic.officer_id=p.id LEFT JOIN (SELECT officer_id, COUNT(*) AS resolved_count FROM public.incidents WHERE created_at>=p_since AND status IN ('resolved','closed') GROUP BY officer_id) ir ON ir.officer_id=p.id LEFT JOIN (SELECT officer_id, COUNT(*) AS evidence_count FROM public.evidence WHERE uploaded_at>=p_since GROUP BY officer_id) ev ON ev.officer_id=p.id WHERE p.role!='citizen' ORDER BY incidents_created DESC; END; $$;

-- DANGEROUS ROADS & REPEAT OFFENDERS
CREATE OR REPLACE FUNCTION public.get_dangerous_roads(p_limit INTEGER DEFAULT 10) RETURNS TABLE(road TEXT, count BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT COALESCE(i.location_address,'Unknown'), COUNT(*)::BIGINT FROM public.incidents i WHERE i.location_address IS NOT NULL AND i.location_address!='' GROUP BY i.location_address ORDER BY count DESC LIMIT p_limit; END; $$;
CREATE OR REPLACE FUNCTION public.get_repeat_offenders(p_threshold INTEGER DEFAULT 3) RETURNS TABLE(plate TEXT, count BIGINT) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT i.vehicle_plate, COUNT(*)::BIGINT FROM public.incidents i WHERE i.vehicle_plate IS NOT NULL AND i.vehicle_plate!='' GROUP BY i.vehicle_plate HAVING COUNT(*)>=p_threshold ORDER BY count DESC; END; $$;

-- PREDICTIVE ANALYTICS
CREATE OR REPLACE FUNCTION public.get_predicted_hotspots(p_days INTEGER DEFAULT 7) RETURNS TABLE(location_address TEXT, risk_level TEXT, confidence REAL) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT i.location_address, CASE WHEN COUNT(*)>=10 THEN 'high' WHEN COUNT(*)>=5 THEN 'moderate' ELSE 'low' END, LEAST(COUNT(*)::REAL/10.0,1.0) FROM public.incidents i WHERE i.created_at>=now()-interval '30 days' AND i.location_address IS NOT NULL AND i.location_address!='' GROUP BY i.location_address ORDER BY COUNT(*) DESC LIMIT 20; END; $$;

-- SYSTEM SETTINGS
CREATE OR REPLACE FUNCTION public.set_system_setting(p_key TEXT, p_value JSONB, p_category TEXT DEFAULT 'general', p_description TEXT DEFAULT NULL, p_is_public BOOLEAN DEFAULT false) RETURNS public.system_settings LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v_result public.system_settings; BEGIN INSERT INTO public.system_settings(key,value,category,description,is_public,updated_by) VALUES(p_key,p_value,p_category,p_description,p_is_public,auth.uid()) ON CONFLICT(key) DO UPDATE SET value=EXCLUDED.value, category=COALESCE(EXCLUDED.category,public.system_settings.category), description=COALESCE(EXCLUDED.description,public.system_settings.description), is_public=COALESCE(EXCLUDED.is_public,public.system_settings.is_public), updated_by=EXCLUDED.updated_by, updated_at=now() RETURNING * INTO v_result; RETURN v_result; END; $$;

-- AUDIT FUNCTIONS
CREATE OR REPLACE FUNCTION public.get_audit_stats(p_from TIMESTAMPTZ DEFAULT (now()-interval '30 days'), p_to TIMESTAMPTZ DEFAULT now()) RETURNS TABLE(total_events BIGINT, critical_events BIGINT, warning_events BIGINT, error_events BIGINT, info_events BIGINT, unique_users BIGINT, top_actions JSONB, daily_counts JSONB) LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN RETURN QUERY SELECT COUNT(*)::BIGINT, COUNT(*) FILTER(WHERE severity='critical')::BIGINT, COUNT(*) FILTER(WHERE severity='warning')::BIGINT, COUNT(*) FILTER(WHERE severity='error')::BIGINT, COUNT(*) FILTER(WHERE severity='info')::BIGINT, COUNT(DISTINCT performed_by)::BIGINT, (SELECT COALESCE(jsonb_agg(jsonb_build_object('action',a.action,'count',a.cnt)),'[]'::jsonb) FROM (SELECT action, COUNT(*) AS cnt FROM public.audit_logs WHERE created_at BETWEEN p_from AND p_to GROUP BY action ORDER BY cnt DESC LIMIT 10) a), (SELECT COALESCE(jsonb_agg(jsonb_build_object('date',d.date,'count',d.cnt)),'[]'::jsonb) FROM (SELECT to_char(created_at,'YYYY-MM-DD') AS date, COUNT(*) AS cnt FROM public.audit_logs WHERE created_at BETWEEN p_from AND p_to GROUP BY date ORDER BY date) d) FROM public.audit_logs WHERE created_at BETWEEN p_from AND p_to; END; $$;
CREATE OR REPLACE FUNCTION public.create_audit_log(p_action TEXT, p_target_type TEXT DEFAULT NULL, p_target_id TEXT DEFAULT NULL, p_description TEXT DEFAULT '', p_severity TEXT DEFAULT 'info', p_metadata JSONB DEFAULT '{}') RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v_id UUID; BEGIN INSERT INTO public.audit_logs(action,performed_by,target_type,target_id,description,severity,metadata) VALUES(p_action,auth.uid(),p_target_type,p_target_id,p_description,p_severity,p_metadata) RETURNING id INTO v_id; RETURN v_id; END; $$;

-- GLOBAL SEARCH
CREATE OR REPLACE FUNCTION public.global_search(p_query TEXT DEFAULT '', p_type_filter TEXT DEFAULT 'all', p_status_filter TEXT DEFAULT NULL, p_severity_filter TEXT DEFAULT NULL, p_date_from TIMESTAMPTZ DEFAULT NULL, p_date_to TIMESTAMPTZ DEFAULT NULL, p_limit INTEGER DEFAULT 20, p_offset INTEGER DEFAULT 0) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v_results JSONB; v_total INTEGER; v_search_term TEXT:='%'||COALESCE(p_query,'')||'%'; v_tsquery TSQUERY; BEGIN IF LENGTH(COALESCE(p_query,''))>=2 THEN BEGIN v_tsquery:=plainto_tsquery('english',p_query); EXCEPTION WHEN OTHERS THEN v_tsquery:=NULL; END; ELSE v_tsquery:=NULL; END IF; WITH search_results AS (SELECT 'incident' AS result_type, i.id::TEXT AS result_id, i.title AS title, COALESCE(i.description,'') AS description, i.status::TEXT AS status, i.severity::TEXT AS severity, i.vehicle_plate AS plate, i.location_address AS location, i.created_at::TEXT AS created_at, NULL::TEXT AS person_name, i.officer_id::TEXT AS ref_id, CASE WHEN v_tsquery IS NOT NULL AND i.title ILIKE v_search_term THEN 3 WHEN v_tsquery IS NOT NULL AND i.description ILIKE v_search_term THEN 2 WHEN v_tsquery IS NOT NULL AND i.vehicle_plate ILIKE v_search_term THEN 4 WHEN i.title ILIKE v_search_term THEN 2 WHEN i.description ILIKE v_search_term THEN 1 WHEN i.vehicle_plate ILIKE v_search_term THEN 3 ELSE 0 END AS relevance FROM public.incidents i WHERE (p_query IS NULL OR p_query='' OR i.title ILIKE v_search_term OR i.description ILIKE v_search_term OR i.vehicle_plate ILIKE v_search_term OR i.location_address ILIKE v_search_term OR i.id::text ILIKE v_search_term OR i.officer_notes ILIKE v_search_term) AND (p_type_filter IS NULL OR p_type_filter='incident' OR p_type_filter='all') AND (p_status_filter IS NULL OR i.status::TEXT=p_status_filter::TEXT) AND (p_severity_filter IS NULL OR i.severity::TEXT=p_severity_filter::TEXT) AND (p_date_from IS NULL OR i.created_at>=p_date_from) AND (p_date_to IS NULL OR i.created_at<=p_date_to) UNION ALL SELECT 'evidence', e.id::TEXT, COALESCE(e.description,''), e.mime_type, e.evidence_status, NULL, NULL, NULL, e.uploaded_at::TEXT, NULL, e.officer_id::TEXT, CASE WHEN e.description ILIKE v_search_term THEN 2 WHEN e.mime_type ILIKE v_search_term THEN 1 ELSE 0 END FROM public.evidence e WHERE (p_query IS NULL OR p_query='' OR e.description ILIKE v_search_term OR e.mime_type ILIKE v_search_term OR e.officer_notes ILIKE v_search_term OR e.id::text ILIKE v_search_term) AND (p_type_filter IS NULL OR p_type_filter='evidence' OR p_type_filter='all') UNION ALL SELECT 'anpr', a.id::TEXT, a.plate_text, 'Confidence: '||ROUND(a.plate_confidence::numeric*100,0)||'%', CASE WHEN a.officer_verified THEN 'verified' ELSE 'pending' END, NULL, a.normalized_plate, NULL, a.scanned_at::TEXT, NULL, a.officer_id::TEXT, CASE WHEN a.plate_text ILIKE v_search_term THEN 5 WHEN a.normalized_plate ILIKE v_search_term THEN 4 ELSE 0 END FROM public.anpr_scans a WHERE (p_query IS NULL OR p_query='' OR a.plate_text ILIKE v_search_term OR a.normalized_plate ILIKE v_search_term) AND (p_type_filter IS NULL OR p_type_filter='anpr' OR p_type_filter='all') UNION ALL SELECT 'citizen_report', cr.id::TEXT, COALESCE(cr.violation_type,cr.report_type), cr.description, cr.status, NULL, cr.vehicle_plate, cr.location_address, cr.created_at::TEXT, cr.reporter_name, cr.citizen_id::TEXT, CASE WHEN cr.description ILIKE v_search_term THEN 2 WHEN cr.violation_type ILIKE v_search_term THEN 2 WHEN cr.vehicle_plate ILIKE v_search_term THEN 3 WHEN cr.reporter_name ILIKE v_search_term THEN 2 WHEN cr.reference_number ILIKE v_search_term THEN 3 ELSE 0 END FROM public.citizen_reports cr WHERE (p_query IS NULL OR p_query='' OR cr.description ILIKE v_search_term OR cr.violation_type ILIKE v_search_term OR cr.vehicle_plate ILIKE v_search_term OR cr.reporter_name ILIKE v_search_term OR cr.reference_number ILIKE v_search_term OR cr.location_address ILIKE v_search_term) AND (p_type_filter IS NULL OR p_type_filter='citizen_report' OR p_type_filter='all') AND (p_status_filter IS NULL OR cr.status=p_status_filter) AND (p_date_from IS NULL OR cr.created_at>=p_date_from) AND (p_date_to IS NULL OR cr.created_at<=p_date_to)) SELECT COALESCE(jsonb_agg(jsonb_build_object('result_type',sr.result_type,'result_id',sr.result_id,'title',sr.title,'description',sr.description,'status',sr.status,'severity',sr.severity,'plate',sr.plate,'location',sr.location,'created_at',sr.created_at,'person_name',sr.person_name,'ref_id',sr.ref_id,'relevance',sr.relevance) ORDER BY sr.relevance DESC, sr.created_at DESC),'[]'::jsonb) INTO v_results FROM search_results sr; v_total:=jsonb_array_length(v_results); RETURN jsonb_build_object('results',COALESCE(v_results,'[]'::jsonb),'total',COALESCE(v_total,0),'limit',p_limit,'offset',p_offset); END; $$;

-- AUTO-UPDATE TRIGGERS
CREATE TRIGGER update_profiles_updated_at BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER update_incidents_updated_at BEFORE UPDATE ON public.incidents FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER update_evidence_updated_at BEFORE UPDATE ON public.evidence FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER update_vehicles_updated_at BEFORE UPDATE ON public.vehicles FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER update_sync_queue_updated_at BEFORE UPDATE ON public.sync_queue FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
CREATE TRIGGER update_system_settings_updated_at BEFORE UPDATE ON public.system_settings FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();
